// A simple wrapped cost: residuals are a deterministic linear combination
// of all parameters. Parameter block layout and residual count are set at
// construction. Jacobians are consistent with the residual mapping.
struct WrappedCost final : ceres::CostFunction {
  WrappedCost(int num_blocks, const std::vector<int>& block_sizes, int num_residuals) {
    set_num_residuals(num_residuals);
    auto* p = mutable_parameter_block_sizes();
    p->reserve(num_blocks);
    for (int s : block_sizes) p->push_back(s);
  }
  bool Evaluate(double const* const* parameters,
                double* residuals,
                double** jacobians) const override {
    const std::vector<int32_t>& sizes = parameter_block_sizes();
    const int R = num_residuals();
    // Residual r := sum of selected parameters; initialize to zero.
    for (int i = 0; i < R; ++i) residuals[i] = 0.0;
    for (int b = 0; b < static_cast<int>(sizes.size()); ++b) {
      const int sz = sizes[b];
      for (int k = 0; k < sz; ++k) {
        const double v = parameters[b][k];
        const int mapped_r = (b + k) % R;
        residuals[mapped_r] += v * (1.0 + 0.1 * (b + 1));
      }
    }
    if (jacobians) {
      for (int b = 0; b < static_cast<int>(sizes.size()); ++b) {
        if (!jacobians[b]) continue;  // Skip blocks caller doesn't want.
        const int sz = sizes[b];
        // Block layout: R rows by sz cols, row-major as per Ceres convention.
        for (int r = 0; r < R; ++r) {
          for (int c = 0; c < sz; ++c) {
            const int mapped_r = (b + c) % R;
            jacobians[b][r * sz + c] = (r == mapped_r) ? (1.0 + 0.1 * (b + 1)) : 0.0;
          }
        }
      }
    }
    return true;
  }
};

// A conditioner cost that maps a 1D input z to alpha*z with jacobian alpha.
// Must be a 1x1 CostFunction as required by ConditionedCostFunction.
struct ConditionerCost final : ceres::CostFunction {
  explicit ConditionerCost(double alpha) : alpha_(alpha) {
    set_num_residuals(1);
    mutable_parameter_block_sizes()->push_back(1);
  }
  bool Evaluate(double const* const* parameters,
                double* residuals,
                double** jacobians) const override {
    const double z = parameters[0][0];
    residuals[0] = alpha_ * z;
    if (jacobians && jacobians[0]) {
      jacobians[0][0] = alpha_;
    }
    return true;
  }
  double alpha_;
};

