// Create a minimal concrete CostFunction to exercise the base-class constructor paths and APIs.
// Randomize a small, valid signature and implement Evaluate to fill residuals and jacobians.
class FuzzCostFunction : public ceres::CostFunction {
 public:
  FuzzCostFunction(const std::vector<int>& block_sizes, int num_residuals) {
    // Configure signature metadata using protected helpers from CostFunction.
    for (int s : block_sizes) { mutable_parameter_block_sizes()->push_back(s); }
    set_num_residuals(num_residuals);
  }
  bool Evaluate(double const* const* parameters,
                double* residuals,
                double** jacobians) const override {
    const std::vector<int32_t>& sizes = parameter_block_sizes();
    const int nb = static_cast<int>(sizes.size());
    const int nr = num_residuals();

    // Simple linear model: residual[r] = sum_{i,k} w(r,i) * parameters[i][k]
    // with w(r,i) = (r+1) / (i+1). Jacobians are consistent with this model.
    for (int r = 0; r < nr; ++r) {
      double acc = 0.0;
      for (int i = 0; i < nb; ++i) {
        const double w = static_cast<double>(r + 1) / static_cast<double>(i + 1);
        for (int k = 0; k < sizes[i]; ++k) { acc += w * parameters[i][k]; }
      }
      residuals[r] = acc;
    }
    if (jacobians != nullptr) {
      for (int i = 0; i < nb; ++i) {
        if (!jacobians[i]) continue;
        const int bs = sizes[i];
        for (int r = 0; r < nr; ++r) {
          const double w = static_cast<double>(r + 1) / static_cast<double>(i + 1);
          for (int k = 0; k < bs; ++k) {
            jacobians[i][r * bs + k] = w; // d residual[r] / d parameters[i][k]
          }
        }
      }
    }
    return true;
  }
};

