// Harness for Plus(x, delta, x_plus_delta).
// Creates a dynamic-sized manifold and random but valid buffers respecting sizes and non-aliasing.
{
  const unsigned int r = *FUZZ_PARAM(unsigned int);
  const int size = 2 + static_cast<int>(r % 7); // 2..8
  ceres::LineManifold<ceres::DYNAMIC> m(size);

  const int x_len = 2 * size;
  const int delta_len = 2 * (size - 1);

  // Use FUZZ_PARAM for an array pool of doubles; note the array-pointer type.
  const double (*pool)[2048] = FUZZ_PARAM(double[2048]);
  int idx = static_cast<int>(*FUZZ_PARAM(unsigned int) % 2048);
  auto next_double = [&]() { const double v = (*pool)[idx]; idx = (idx + 1) % 2048; return v; };

  // Build x = [origin(size), direction(size)] and ensure direction is unit-like.
  std::vector<double> x(x_len);
  for (int i = 0; i < x_len; ++i) x[i] = next_double();
  double norm_d2 = 0.0;
  for (int i = 0; i < size; ++i) norm_d2 += x[size + i] * x[size + i];
  double norm_d = std::sqrt(norm_d2);
  if (!(norm_d > 1e-12)) {
    for (int i = 0; i < size; ++i) x[size + i] = 0.0;
    x[size + 0] = 1.0; // fallback to e1
  } else {
    for (int i = 0; i < size; ++i) x[size + i] /= norm_d;
  }

  // Build delta = [delta_o(size-1), delta_d(size-1)].
  std::vector<double> delta(delta_len);
  for (int i = 0; i < delta_len; ++i) delta[i] = next_double();

  // Output buffer x_plus_delta must not alias x or delta.
  std::vector<double> x_plus_delta(x_len, 0.0);

  // Invoke Plus and validate return value.
  const bool ok = m.Plus(x.data(), delta.data(), x_plus_delta.data());
  if (!ok) { FUZZ_BAIL(); }

  // Sanity: resulting direction should be finite and non-zero.
  double dir_norm2 = 0.0;
  for (int i = 0; i < size; ++i) {
    const double v = x_plus_delta[size + i];
    FUZZ_ASSERT(std::isfinite(v) != 0, "Non-finite in Plus result");
    dir_norm2 += v * v;
  }
  FUZZ_ASSERT(dir_norm2 > 0.0, "Zero direction after Plus");
}
